node.doctext:
I don't know perl, so I don't know what builds the %form hash and other variables.
<c>
# Create invoice and Prepare for emailing
        $message  = "\n$sheader\n";
        $message .= "$saddress\n";
        $message .= "$sphone\n\n";
	$message .= "\n";
        $message .= "Date: $date\n"; 
        $message .= "Invoice No: $inv_num\n"; 
        $message .= "Customer Id: $sessionid\n\n"; 
        $message .= "---------------------------------------------\n";
	$message .= "Qty\t  Description\t\t\t\t\t  Amount\n";
        $message .= "---------------------------------------------\n";
	$message .= " 1 \t  $description\t  $amount\n";
 	$message .= "---------------------------------------------\n";

	my $total = sprintf("TOTAL: %5.2f", $amount);

	$message .= "$total\n\n";
	$message .= "PAYMENT METHOD: $method\n\n";
	$message .= " Payment Type: $payment_type\n";
	$message .= " Payment Date: $payment_date\n";
	$message .= " Payment Status: $payment_status : $payment\n";
	$message .= " Account Status: $payer_status\n";
	$message .= " Address Status: $address_status\n";
	$message .= " Transcation ID: $auth_code\n\n";
	$message .= "SessionID: $sessionid\n\n";
	$message .= "BILLING ADDRESS:\n\n";
	$message .= "--"." $fname $lname\n";
	$message .= "--"." $address\n";
	$message .= "--"." $city, $state\. $zip\n";
	$message .= "--"." $country\n";
	$message .= "--"." $phone\n";
	$message .= "--"." $email\n";
	$message .= "\n";
	$message .= "-----------------------------------------------------------\n";
	$message .= "Remote HOST: $ENV{'REMOTE_HOST'}\n";
	$message .= "Remote IP address: $ENV{'REMOTE_ADDR'}\n";
	$message .= "Remote Browser: $ENV{'HTTP_USER_AGENT'}\n";


return $message;

} # end of sub
</c>
